import {tickLoading} from './loading-door.js';
import {tickFrontDoor,startBlackout} from './door-system.js';
import {SITE,siteZone} from './site-layout.js';
export function initUpgrades(s){Object.assign(s,{loadingLift:0,loadingTarget:false,loadingManual:false,loadingBroken:false,refusal:null,spinnerStep:0,spinnerBusy:0,scannerOwned:false,binocularOwned:false,binocularActive:false,binocularZoom:1,securityOpen:false,doorKeyOwned:false,frontLocked:false,frontManual:false,frontSlide:0,frontBatteryUsed:false,boardBuild:null,litter:[],coins:[],coinIncome:0,litterClock:55,coinClock:110,alleyEvent:null,alleyCooldown:0,alleyCount:0,sensorPulseSeen:{},rng:139+s.night*811});return s;}
const rng=s=>{s.rng=(s.rng*1664525+1013904223)>>>0;return s.rng/4294967296;};
export function buildProgress(g,dt,held){const s=g.s,b=s.boardBuild;if(!b)return false;if(!s.boardCarry||s.finished||s.paused)return false;if(Math.hypot(s.player.x-b.x,s.player.z-b.z)>.9||s.doors[b.key]||(b.key==='loading'&&(s.loadingLift||0)>.02)){s.boardBuild=null;g.notice('安装中止，木板仍在手中。');return false;}b.grace=held?.24:(b.grace||0)-dt;if(b.grace<0){s.boardBuild=null;return false;}b.time+=dt;const hit=Math.floor(b.time/.23);if(hit>(b.hit||0)){b.hit=hit;g.sound(b.key==='loading'?'metalKey':'hammer',{pos:{x:s.player.x,z:s.player.z}});}if(b.time>=.95){s.barricades[b.key]++;s.boardCarry=false;s.boardBuild=null;if(b.key==='front')s.frontLocked=true;g.notice((b.key==='loading'?'木板已卡入固定槽 · ':'木板已钉牢 · ')+s.barricades[b.key]+'/3');return true;}return false;}
export function tickUpgrades(g,dt){const s=g.s;tickFrontDoor(s,dt,g.sound);tickLoading(s,dt,g.sound);s.spinnerBusy=Math.max(0,(s.spinnerBusy||0)-dt);for(const id of Object.keys(s.spinnerBusies||{}))s.spinnerBusies[id]=Math.max(0,s.spinnerBusies[id]-dt);if(s._lastPower!==s.power){if(!s.power){startBlackout(s);g.sound('lightFlicker');}s._lastPower=s.power;}
 if(['opening','customers'].includes(s.phase)){s.litterClock-=dt;s.coinClock-=dt;if(s.litterClock<=0){s.litterClock=58+rng(s)*30;if(s.litter.length<5){const p=freeFloor(g,s);if(p)s.litter.push({...p,id:'l'+Math.floor(s.time*10),type:rng(s)>.5?'paper':'stain'});}}if(s.coinClock<=0){s.coinClock=115+rng(s)*55;if(s.coins.length<3){const p=freeFloor(g,s);if(p)s.coins.push({...p,id:'c'+Math.floor(s.time*10),value:[10,25,50][Math.floor(rng(s)*3)],born:s.time});}}}
 s.alleyCooldown=Math.max(0,s.alleyCooldown-dt);if(['outage','siege','incident'].includes(s.phase)&&siteZone(s.player)==='outside'&&s.alleyCooldown===0){const spots=[{x:21.3,z:12.9},{x:20.7,z:21.1}],i=spots.findIndex(p=>Math.hypot(p.x-s.player.x,p.z-s.player.z)<3.2);if(i>=0){s.alleyCount++;s.alleyEvent={bin:i,time:s.time,threat:s.night===3&&s.alleyCount===2};s.alleyCooldown=65+rng(s)*25;g.sound('binRattle',{pos:spots[i]});if(s.alleyEvent.threat&&!s.threats.some(t=>t.mode!=='dead')){s.threats.push({id:'alley-'+s.night,sourceId:'cal',x:21,z:16,yaw:0,hp:1,mode:'search',side:'front',stun:0,bash:0,route:null,repath:0,search:9,last:{x:s.player.x,z:s.player.z}});g.sound('growl',{pos:{x:21,z:16}});}else if(s.night>=2)s.shadow={x:21.25,z:15.6,until:s.time+1.3};}}
}
function freeFloor(g,s){for(let n=0;n<20;n++){const p={x:-5.0+rng(s)*13.7,z:-2.8+rng(s)*10};if(g.canOccupy(p,s)&&!(s.actors||[]).some(a=>Math.hypot(a.x-p.x,a.z-p.z)<.8)&&![...s.coins,...s.litter].some(a=>Math.hypot(a.x-p.x,a.z-p.z)<.7))return p;}return null;}
